macro.command:
const actorClasses = actor.classes;
const classKeys = Object.keys(actorClasses);
const target = workflow.targets.first();
if (!target) return;
let totalTempHp = 0;
let totalTempHpDice = [];
let totalFormula = [];
let diceList = [];
let chatList = [];

const totalHitDice = classKeys.reduce((acc, key) => acc + (parseInt(actorClasses[key].system.levels) - parseInt(actorClasses[key].system.hd.spent)), 0);
if (totalHitDice === 0) {
	return ui.notifications.warn("You have no hit dice remaining.");
}

let content = `<p>${game.i18n.localize("GAMBITSPREMADES.Dialogs.TransientHealing.SelectHitDice")}</p>`;

for (const key of classKeys) {
	const cls = actorClasses[key];
	const hitDiceAvailable = parseInt(cls.system.levels) - parseInt(cls.system.hd.spent);
	let hitDiceRollType = cls.system.hd.denomination;

	if (hitDiceAvailable === 0) continue;

content += `
<div class="form-group">
	<label style="flex: 0 0 auto; margin: 0 10px; text-align: left;">${foundry.utils.escapeHTML(cls.name)} - ${game.i18n.localize("GAMBITSPREMADES.Dialogs.TransientHealing.Available")}: <b>${hitDiceAvailable}${hitDiceRollType}</b></label>
	<div class="form-fields">
		<button type="button" class="hit-dice-decrement" data-key="${key}">-</button>
		<span id="hitDiceDisplay-${key}" style="flex: 0 0 auto; margin: 0 10px; text-align: center;">0</span>
		<button type="button" class="hit-dice-increment" data-key="${key}">+</button>
	</div>
</div>
`;
}



await game.gps.showAutomationDialog({
	window: {title: game.i18n.localize("GAMBITSPREMADES.Dialogs.TransientHealing.Title")},
	content: content,
	buttons: [
	{
		action: "recover",
		label: game.i18n.localize("GAMBITSPREMADES.Dialogs.Window.Continue"),
		callback: async (event, button, dialog) => {
		const html = dialog.element;
		let hitDiceUsed = false;
		for (const key of classKeys) {
			const display = html.querySelector(`#hitDiceDisplay-${CSS.escape(key)}`);
			if (!display) continue;

			const hitDiceToUse = parseInt(display.textContent);
			if (!isNaN(hitDiceToUse) && hitDiceToUse > 0) {
			hitDiceUsed = true;
			}

			if (!Number.isInteger(hitDiceToUse) || hitDiceToUse <= 0) continue;
			if (hitDiceToUse > actorClasses[key].system.levels - actorClasses[key].system.hd.spent) return;

			const hitDiceRemaining = parseInt(actorClasses[key].system.hd.spent) + hitDiceToUse;
			await actorClasses[key].update({ 'system.hd.spent': hitDiceRemaining });

			const hitDiceRollType = actorClasses[key].system.hd.denomination;
			let tempHpRoll = await new Roll(`${hitDiceToUse}${hitDiceRollType}`,actor.getRollData()).evaluate();
			await MidiQOL.displayDSNForRoll(tempHpRoll, 'damageRoll')
			tempHpRoll.dice.forEach(die => {die.results.forEach(rollResult => {diceList.push(`<li class="roll die ${hitDiceRollType}">${rollResult.result}</li>`);});});
			totalTempHp += tempHpRoll.total;
			totalTempHpDice.push(tempHpRoll.total);
			totalFormula.push(tempHpRoll.formula);
		}

			if (!hitDiceUsed) return ui.notifications.warn("You did not select any hit dice to use.");
			const currentTempHp = target.actor.system.attributes.hp.temp;
			if(currentTempHp >=totalTempHp) return ui.notifications.warn(`${target.actor.name} already has more temporary hit points than you are able to give.`);
			chatList = `<div class="flexrow 2"><div class="midi-qol-damage-roll"><div style="text-align:center">(Temporary HP)</div><div class="dice-roll"><div class="dice-result"><h4 class="dice-total">${totalTempHp}</h4><div class="dice-tooltip"><section class="tooltip-part"><div class="dice"><header class="part-header flexrow"><span class="part-formula">${totalFormula.join(' + ')}</span><span class="part-total">${totalTempHpDice.join(' + ')}</span></header><ol class="dice-rolls">${diceList.join('')}</ol></div></section></div></div></div><div class="end-midi-qol-damage-roll"></div></div></div><div class="midi-qol-flex-container"><div class="midi-qol-target-npc midi-qol-target-name" id="${target.id}"></br>${target.actor.name} receives ${totalTempHp} temporary hit points.</div><div><img src="${target.actor.img}" width="30" height="30" style="border:0px"></div></div>`;
			await target.actor.applyTempHP(totalTempHp);
			let healResults = `<div><div class="midi-qol-nobox">${chatList}</div></div>`;
			return await game.gps.replaceChatCard({ actorUuid: actor.uuid, itemUuid: macroItem.uuid, itemCardUuid: args[0].itemCardUuid, chatContent: healResults });
		}
	},
		{
			action: "cancel",
			default: true,
			label: game.i18n.localize("GAMBITSPREMADES.Dialogs.Common.Cancel"),
			callback: () => false
		}
	],
render: (event) => {
	const html = event.target.element;
	html.addEventListener('click', event => {
		const targetClick = event.target;
		const isIncrement = targetClick.classList.contains('hit-dice-increment');
		const isDecrement = targetClick.classList.contains('hit-dice-decrement');

		if (isIncrement || isDecrement) {
			const key = targetClick.dataset.key;
			const spanDisplay = html.querySelector(`#hitDiceDisplay-${key}`);
			let currentValue = parseInt(spanDisplay.textContent);
			const maxValue = parseInt(actorClasses[key].system.levels) - parseInt(actorClasses[key].system.hd.spent);

			if (isIncrement && currentValue < maxValue) {
			spanDisplay.textContent = currentValue + 1;
			} else if (isDecrement && currentValue > 0) {
			spanDisplay.textContent = currentValue - 1;
			}
		}
	});
}
});
